import{_ as e,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"RH InkTank Ceph Day Sessions Asaf Wachtel MELLANOX","description":"","frontmatter":{"title":"RH InkTank Ceph Day Sessions Asaf Wachtel MELLANOX","date":"2014-07-25T00:00:00.000Z","updated":"2014-07-26T00:00:00.000Z","tags":["Ceph","高性能网络","分布式存储","Melanox","Hadoop"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/RH_InkTank_Ceph_Day_Sessions_Asaf_Wachtel_MELLANOX.md","filePath":"posts/2014/RH_InkTank_Ceph_Day_Sessions_Asaf_Wachtel_MELLANOX.md","lastUpdated":1780459816000}'),h={name:"posts/2014/RH_InkTank_Ceph_Day_Sessions_Asaf_Wachtel_MELLANOX.md"};function t(s,a,r,n,p,d){return l(),i("div",null,[...a[0]||(a[0]=[o('<p>会议纪要</p><h3 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h3><p>[请填写会议时间]</p><h3 id="会议地点" tabindex="-1">会议地点： <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点：&quot;">​</a></h3><p>[请填写会议地点]</p><h3 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h3><ul><li>Asaf（Melanox企业及云业务发展负责人）</li><li>[其他参会人员姓名]</li></ul><h3 id="会议议程" tabindex="-1">会议议程： <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程：&quot;">​</a></h3><h4 id="介绍与背景" tabindex="-1">介绍与背景 <a class="header-anchor" href="#介绍与背景" aria-label="Permalink to &quot;介绍与背景&quot;">​</a></h4><ul><li>Asaf介绍了Melanox公司，作为高性能服务器、存储和连接解决方案的领先提供商，Melanox提供从网络适配器到交换机、从10Gbps到56Gbps的全套产品。</li><li>公司业务始于1999年，现有约1500名员工，年收入约5亿美元，最初服务于高性能计算（HPC）领域，后扩展到存储、云计算、Web 2.0等行业。</li></ul><h4 id="网络在ceph世界中的作用" tabindex="-1">网络在Ceph世界中的作用 <a class="header-anchor" href="#网络在ceph世界中的作用" aria-label="Permalink to &quot;网络在Ceph世界中的作用&quot;">​</a></h4><ul><li>Asaf强调高性能网络对于Ceph的重要性，特别是对于数据的高可用性和大规模数据传输。</li><li>他指出，Ceph集群的性能和可用性高度依赖于高性能网络，包括无损、高带宽、低延迟和CPU卸载。</li></ul><h4 id="ceph部署案例" tabindex="-1">Ceph部署案例 <a class="header-anchor" href="#ceph部署案例" aria-label="Permalink to &quot;Ceph部署案例&quot;">​</a></h4><ul><li>Asaf分享了一个8.5PB Ceph集群部署案例，该集群用于Web环境，对性能要求极高。</li><li>该案例中，后端网络采用40Gbps以太网，前端网络采用10Gbps和40Gbps以太网，以支持SSD的使用。</li></ul><h4 id="高性能网络部署指南" tabindex="-1">高性能网络部署指南 <a class="header-anchor" href="#高性能网络部署指南" aria-label="Permalink to &quot;高性能网络部署指南&quot;">​</a></h4><ul><li>Melanox提供了一份关于高性能网络部署的指南，详细介绍了所需硬件和配置。</li><li>指南中包含了两个用例：10Gbps以太网公共网络和40Gbps以太网公共网络。</li></ul><h4 id="hadoop与ceph的协同" tabindex="-1">Hadoop与Ceph的协同 <a class="header-anchor" href="#hadoop与ceph的协同" aria-label="Permalink to &quot;Hadoop与Ceph的协同&quot;">​</a></h4><ul><li>Melanox一直在研究如何优化Hadoop的网络配置，以提高性能。</li><li>他们发现，将HDFS替换为Ceph的SEFS可以提供统一的存储体验，并提高性能。</li><li>他们还进行了一项研究，展示了SEFS在Terasort基准测试中的性能提升。</li></ul><h4 id="硬件优化" tabindex="-1">硬件优化 <a class="header-anchor" href="#硬件优化" aria-label="Permalink to &quot;硬件优化&quot;">​</a></h4><ul><li>Melanox开发了Excelo API，用于简化RDMA编程，并支持多种传输方式。</li><li>Excelo API可以帮助应用更容易地集成RDMA，并提高性能。</li></ul><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h4><ul><li>Ceph对高性能网络的需求很高，Melanox提供了一系列解决方案，包括高性能网络设备和软件。</li><li>Melanox将继续致力于优化Ceph的性能和可用性。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>[请填写后续行动计划，例如：与客户合作部署高性能网络、优化Excelo API、参与Ceph社区等]</li></ul><h3 id="关键词" tabindex="-1">关键词： <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词：&quot;">​</a></h3><ul><li>Ceph</li><li>分布式存储</li><li>高性能网络</li><li>40Gbps以太网</li><li>56Gbps以太网</li><li>RDMA</li><li>Excelo API</li><li>高性能计算</li><li>云计算</li><li>Hadoop</li></ul>',26)])])}const _=e(h,[["render",t]]);export{u as __pageData,_ as default};
